def interp(T, T_list, val_list):
    if T <= T_list[0]:
        return val_list[0]
    if T >= T_list[-1]:
        return val_list[-1]
    for i in range(len(T_list) - 1):
        if T_list[i] <= T <= T_list[i+1]:
            frac = (T - T_list[i]) / (T_list[i+1] - T_list[i])
            return val_list[i] + frac * (val_list[i+1] - val_list[i])

def get_props(coolant, T):
    c = coolants_db[coolant]
    return {
        'rho': interp(T, c['T'], c['rho']),
        'cp': interp(T, c['T'], c['cp']),
        'mu': interp(T, c['T'], c['mu']),
        'k': interp(T, c['T'], c['k'])
    }

def f_friction(Re):
    return 64.0 / Re if Re < 2300 else 0.316 * (Re ** -0.25)

def nusselt(Re, Pr):
    return 4.36 if Re < 2300 else 0.023 * (Re ** 0.8) * (Pr ** 0.4)

def pump_pressure(Qv_Lmin, s, pump_id):
    curve = pumps_db[pump_id]['curve']
    Qv_full = [x[0] for x in curve]
    dP_full = [x[1] for x in curve]
    Qv_scaled = Qv_Lmin / s
    dP_at_full = interp(Qv_scaled, Qv_full, dP_full)
    return s * s * dP_at_full

def bisect(f, a, b, tol=1e-6):
    fa, fb = f(a), f(b)
    if fa * fb > 0:
        return None
    for _ in range(100):
        mid = (a + b) / 2
        fmid = f(mid)
        if abs(b - a) < tol or abs(fmid) < 1e-3:
            return mid
        if fa * fmid < 0:
            b, fb = mid, fmid
        else:
            a, fa = mid, fmid
    return (a + b) / 2

def evaluate(coolant, pump_id, speed, d_mm, n_par):
    if coolants_db[coolant]['freeze'] > -5:
        return None

    def residual(Qv_Lmin):
        T_out = T_in + 2.0
        for _ in range(15):
            T_mean = (T_in + T_out) / 2
            props = get_props(coolant, T_mean)
            Qv = Qv_Lmin / 60000
            T_out = T_in + Q_heat / (props['rho'] * Qv * props['cp'])

        T_mean = (T_in + T_out) / 2
        props = get_props(coolant, T_mean)
        Qv = Qv_Lmin / 60000

        d = d_mm / 1000
        Qv_ch = Qv / n_par
        v_ch = Qv_ch / (3.14159 * d * d / 4)
        Re_ch = props['rho'] * v_ch * d / props['mu']

        f_ch = f_friction(Re_ch)
        dP_ch = f_ch * (L_ch / d) * props['rho'] * v_ch * v_ch / 2

        v_pipe = Qv / (3.14159 * d_pipe * d_pipe / 4)
        Re_pipe = props['rho'] * v_pipe * d_pipe / props['mu']
        f_pipe = f_friction(Re_pipe)
        dP_pipe = (f_pipe * L_pipe / d_pipe + K_fittings) * props['rho'] * v_pipe * v_pipe / 2

        return pump_pressure(Qv_Lmin, speed, pump_id) - (dP_ch + dP_pipe)

    try:
        Qv_op = bisect(residual, 0.2, 30)
    except:
        return None

    if Qv_op is None:
        return None

    T_out = T_in + 2.0
    for _ in range(15):
        T_mean = (T_in + T_out) / 2
        props = get_props(coolant, T_mean)
        Qv = Qv_op / 60000
        T_out = T_in + Q_heat / (props['rho'] * Qv * props['cp'])

    if T_out - T_in > 6:
        return None

    T_mean = (T_in + T_out) / 2
    props = get_props(coolant, T_mean)
    Qv = Qv_op / 60000

    d = d_mm / 1000
    Qv_ch = Qv / n_par
    v_ch = Qv_ch / (3.14159 * d * d / 4)

    if v_ch > 1.0:
        return None

    Re_ch = props['rho'] * v_ch * d / props['mu']

    if 2000 < Re_ch < 3000:
        return None

    Pr = props['mu'] * props['cp'] / props['k']
    Nu = nusselt(Re_ch, Pr)
    h = Nu * props['k'] / d

    q_pp = (Q_heat / n_par) / (3.14159 * d * L_ch)
    T_cell = T_out + q_pp / h + q_cell * R_cp

    if T_cell > 31.5:
        return None

    P_pump = pumps_db[pump_id]['P_rated'] * (speed ** 3)
    if P_pump > 50:
        return None

    cost = pumps_db[pump_id]['price'] + n_par * L_ch * tube_price[d_mm]
    if cost > 35:
        return None

    return {'P_pump': P_pump, 'cost': cost, 'T_cell': T_cell, 'T_out': T_out}

